// Sky Courier: Ring Run — a small original arcade flight game.
// Chase view behind a prop courier plane over a procedural valley.
// Pure Canvas 2D + a tiny software 3D projector. No libraries, no network,
// no external assets: every pixel and sound is generated by this file.
// Controls: arrows pitch/bank, W/S throttle, mouse steers, P pause, R restart,
// M mute, Enter/click start. Fly the 12 rings, then land back on the runway.
'use strict';

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = 1280, H = 800;

// ---------- deterministic RNG ----------
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const params = new URLSearchParams(location.search);
const SEED = parseInt(params.get('seed') || '1', 10) || 1;
const rng = mulberry32(SEED * 2654435761 >>> 0);

// Smooth value noise in 2D, deterministic from integer lattice + seed.
function hash2(ix, iz) {
  let h = (ix * 374761393 + iz * 668265263 + SEED * 974634211) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return (((h ^ (h >>> 16)) >>> 0) / 4294967296);
}
function smooth(t) { return t * t * (3 - 2 * t); }
function vnoise(x, z) {
  const ix = Math.floor(x), iz = Math.floor(z);
  const fx = x - ix, fz = z - iz;
  const a = hash2(ix, iz), b = hash2(ix + 1, iz), c = hash2(ix, iz + 1), d = hash2(ix + 1, iz + 1);
  const u = smooth(fx), v = smooth(fz);
  return (a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v) * 2 - 1;
}
function fbm(x, z) {
  return vnoise(x, z) * 0.55 + vnoise(x * 2.13 + 7.3, z * 2.13 - 3.1) * 0.3 + vnoise(x * 4.7 - 2.2, z * 4.7 + 5.9) * 0.15;
}

// ---------- world ----------
const COURSE_LEN = 12500;      // rings run from z=900 to z=11500, runway at z 0..640
const RING_COUNT = 12;
const RUNWAY = { z0: 0, z1: 640, half: 16 };

// Course centreline meanders gently so the valley never feels straight.
function courseX(z) { return 140 * Math.sin(z * 0.00012) + 40 * Math.sin(z * 0.00031 + 1.7); }
// River bends across the valley, roughly parallel to the course.
function riverX(z) { return 300 * Math.sin(z * 0.00009 + 1.2) + 60; }
// A dirt road winds on the far side of the river.
function roadX(z) { return riverX(z) + 190 + 40 * Math.sin(z * 0.00021 + 0.4); }

function terrainH(x, z) {
  // Rolling hills.
  let h = 16 * Math.sin(x * 0.004 + 1.7) * Math.cos(z * 0.003 - 0.6)
        + 9 * Math.sin(x * 0.011 + 0.5) * Math.sin(z * 0.007 + 2.0)
        + 14 * fbm(x * 0.006, z * 0.006);
  // Flatten the valley floor near the course so rings sit over flyable ground.
  const dc = Math.abs(x - courseX(z));
  const flat = Math.max(0, 1 - dc / 260);
  h *= (1 - flat * 0.75);
  // River carves a channel down to water level (~2m).
  const dr = Math.abs(x - riverX(z));
  if (dr < 30) {
    const k = 1 - dr / 30;
    h = h * (1 - k) + 2 * k;
  }
  // Runway strip is perfectly flat.
  if (z >= RUNWAY.z0 - 40 && z <= RUNWAY.z1 + 40 && Math.abs(x) < 46) h = 0;
  // Mountains rise at the valley edges.
  const edge = Math.max(0, Math.abs(x) - 560);
  h += edge * edge * 0.0016;
  // Far north the valley closes into high ground.
  if (z > 11800) h += (z - 11800) * 0.05;
  if (z < -300) h += (-300 - z) * 0.04;
  return h;
}
function waterAt(x, z) { return Math.abs(x - riverX(z)) < 22 && terrainH(x, z) < 3.2; }

// Rings: position, radius, passed/missed state. Built once, deterministically.
const rings = [];
(function buildCourse() {
  for (let i = 0; i < RING_COUNT; i++) {
    const z = 950 + i * 950;
    const cx = courseX(z);
    const side = (i % 2 === 0) ? 1 : -1;
    const off = side * (30 + ((i * 37) % 110));
    const ground = terrainH(cx + off, z);
    const alt = ground + 55 + ((i * 53) % 70);
    const r = Math.max(11, 21 - i * 0.8);
    rings.push({ x: cx + off, y: alt, z, r, passed: false, missed: false });
  }
})();

// Golden-hour light. 0 = midday, 1 = sunset (used by the landing shot).
let golden = 0;

// ---------- game state ----------
const S = {
  mode: 'title',        // title | playing | paused | crashed | gameover | win | shot
  t: 0,                 // wall time in the current mode
  playT: 0,             // time spent playing
  timeLeft: 150,
  score: 0,
  lives: 3,
  nextRing: 0,
  phase: 'course',      // course | return (fly back and land)
  plane: { x: 0, y: 0, z: 120, yaw: 0, pitch: 0, bank: 0, speed: 0, throttle: 0 },
  cam: { x: 0, y: 60, z: 0, yaw: 0 },
  crashT: 0, invuln: 0, flash: '', flashT: 0,
  wind: 0, windT: 0,
  best: 0, muted: false,
  particles: [],
};
try { S.best = parseInt(localStorage.getItem('skycourier-best') || '0', 10) || 0; } catch (e) { S.best = 0; }
function saveBest() {
  if (S.score > S.best) {
    S.best = S.score;
    try { localStorage.setItem('skycourier-best', String(S.best)); } catch (e) { /* private mode */ }
  }
}

function resetPlane(atStart) {
  const p = S.plane;
  if (atStart) {
    p.x = 0; p.y = 0; p.z = 120; p.yaw = 0; p.pitch = 0; p.bank = 0; p.speed = 0; p.throttle = 0;
  } else {
    // Respawn just behind the last passed ring (or the runway).
    const i = Math.max(0, S.nextRing - 1);
    const r = rings[i];
    p.x = r ? r.x : 0; p.y = (r ? r.y : 60) + 10; p.z = (r ? r.z : 120) - 220;
    p.yaw = 0; p.pitch = 0; p.bank = 0; p.speed = 55; p.throttle = 0.55;
  }
  S.invuln = 2.5;
}
function resetGame() {
  rings.forEach(r => { r.passed = false; r.missed = false; });
  S.score = 0; S.lives = 3; S.nextRing = 0; S.phase = 'course';
  S.timeLeft = 150; S.playT = 0; S.particles = []; S.flash = ''; S.wind = 0;
  resetPlane(true);
}

// ---------- input ----------
const keys = {};
let mouse = { x: W / 2, y: H / 2, active: false };
addEventListener('keydown', e => {
  keys[e.code] = true;
  if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(e.code)) e.preventDefault();
  if (e.code === 'Enter' && (S.mode === 'title' || S.mode === 'gameover' || S.mode === 'win')) startGame();
  if (e.code === 'KeyR' && (S.mode === 'gameover' || S.mode === 'win' || S.mode === 'crashed')) startGame();
  if (e.code === 'KeyP' && S.mode === 'playing') S.mode = 'paused';
  else if (e.code === 'KeyP' && S.mode === 'paused') S.mode = 'playing';
  if (e.code === 'KeyM') S.muted = !S.muted;
});
addEventListener('keyup', e => { keys[e.code] = false; });
canvas.addEventListener('pointermove', e => {
  const r = canvas.getBoundingClientRect();
  mouse.x = (e.clientX - r.left) * (W / r.width);
  mouse.y = (e.clientY - r.top) * (H / r.height);
  mouse.active = true;
});
canvas.addEventListener('pointerdown', e => {
  AudioSys.unlock();
  if (S.mode === 'title' || S.mode === 'gameover' || S.mode === 'win') startGame();
});
function startGame() {
  resetGame();
  S.mode = 'playing';
  AudioSys.unlock();
  AudioSys.click();
}

// ---------- audio: everything synthesized with WebAudio, no files ----------
const AudioSys = {
  ac: null, master: null, engOsc1: null, engOsc2: null, engGain: null, windGain: null,
  unlock() {
    if (this.ac) { if (this.ac.state === 'suspended') this.ac.resume(); return; }
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      this.ac = new AC();
      this.master = this.ac.createGain(); this.master.gain.value = 0.4; this.master.connect(this.ac.destination);
      // Engine drone: two detuned saws through a lowpass.
      const lp = this.ac.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 420; lp.connect(this.master);
      this.engGain = this.ac.createGain(); this.engGain.gain.value = 0; this.engGain.connect(lp);
      this.engOsc1 = this.ac.createOscillator(); this.engOsc1.type = 'sawtooth'; this.engOsc1.frequency.value = 55;
      this.engOsc2 = this.ac.createOscillator(); this.engOsc2.type = 'sawtooth'; this.engOsc2.frequency.value = 82.5;
      this.engOsc1.connect(this.engGain); this.engOsc2.connect(this.engGain);
      this.engOsc1.start(); this.engOsc2.start();
      // Wind: looped noise through a bandpass.
      const len = this.ac.sampleRate * 1;
      const buf = this.ac.createBuffer(1, len, this.ac.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      const src = this.ac.createBufferSource(); src.buffer = buf; src.loop = true;
      const bp = this.ac.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 500; bp.Q.value = 0.6;
      this.windGain = this.ac.createGain(); this.windGain.gain.value = 0;
      src.connect(bp); bp.connect(this.windGain); this.windGain.connect(this.master); src.start();
    } catch (e) { this.ac = null; }
  },
  engine(throttle, speed01) {
    if (!this.ac || S.muted) { if (this.engGain) this.engGain.gain.value = 0; return; }
    const t = this.ac.currentTime;
    this.engGain.gain.setTargetAtTime(0.05 + throttle * 0.10, t, 0.1);
    this.engOsc1.frequency.setTargetAtTime(48 + throttle * 60 + speed01 * 20, t, 0.1);
    this.engOsc2.frequency.setTargetAtTime(72 + throttle * 90 + speed01 * 30, t, 0.1);
    this.windGain.gain.setTargetAtTime(speed01 * speed01 * 0.12, t, 0.2);
  },
  blip(freq, dur, type, vol) {
    if (!this.ac || S.muted) return;
    const t = this.ac.currentTime;
    const o = this.ac.createOscillator(), g = this.ac.createGain();
    o.type = type || 'sine'; o.frequency.value = freq;
    g.gain.setValueAtTime(vol || 0.25, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.02);
  },
  ring() { this.blip(880, 0.18, 'sine', 0.3); setTimeout(() => this.blip(1318, 0.3, 'sine', 0.28), 90); },
  click() { this.blip(660, 0.08, 'square', 0.12); },
  crash() {
    if (!this.ac || S.muted) return;
    const t = this.ac.currentTime;
    const o = this.ac.createOscillator(), g = this.ac.createGain();
    o.type = 'sine'; o.frequency.setValueAtTime(160, t); o.frequency.exponentialRampToValueAtTime(35, t + 0.5);
    g.gain.setValueAtTime(0.5, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.6);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + 0.65);
  },
};

// ---------- physics & rules ----------
function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
function lerp(a, b, t) { return a + (b - a) * t; }
function angLerp(a, b, t) {
  let d = b - a;
  while (d > Math.PI) d -= Math.PI * 2;
  while (d < -Math.PI) d += Math.PI * 2;
  return a + d * t;
}

function update(dt) {
  const p = S.plane;
  S.playT += dt;
  S.timeLeft -= dt;
  if (S.timeLeft <= 0) { S.timeLeft = 0; return gameOver('OUT OF TIME'); }

  // Steering: keyboard first, mouse steers when no arrow keys are held.
  let pitchIn = 0, bankIn = 0;
  if (keys.ArrowUp) pitchIn += 1;
  if (keys.ArrowDown) pitchIn -= 1;
  if (keys.ArrowLeft) bankIn -= 1;
  if (keys.ArrowRight) bankIn += 1;
  if (pitchIn === 0 && bankIn === 0 && mouse.active && S.mode === 'playing') {
    const nx = (mouse.x - W / 2) / (W / 2), ny = (mouse.y - H / 2) / (H / 2);
    bankIn = clamp(nx * 1.4, -1, 1);
    pitchIn = clamp(-ny * 1.2, -1, 1);
  }
  if (keys.KeyW) p.throttle = clamp(p.throttle + dt * 0.7, 0, 1);
  if (keys.KeyS) p.throttle = clamp(p.throttle - dt * 0.9, 0, 1);
  if (S.playT < 1.5 && p.throttle < 0.6) p.throttle = 0.6; // auto throttle at takeoff

  const targetBank = bankIn * 0.9;
  p.bank = lerp(p.bank, targetBank, clamp(dt * 3.2, 0, 1));
  const targetPitch = pitchIn * 0.38;
  p.pitch = lerp(p.pitch, targetPitch, clamp(dt * 2.6, 0, 1));

  // Speed: throttle pushes, drag pulls, climbing costs speed.
  const maxSpd = 42 + p.throttle * 108;
  p.speed += ((maxSpd - p.speed) * 0.25 - Math.sin(p.pitch) * 22) * dt;
  p.speed = clamp(p.speed, 0, 165);

  // Coordinated turn: bank swings the heading, more at higher speed.
  p.yaw += p.bank * (0.35 + p.speed * 0.0032) * dt;

  // Wind gusts in the late course push the plane sideways.
  S.windT += dt;
  if (S.nextRing >= 7) {
    S.wind = Math.sin(S.windT * 0.7) * 6;
  } else S.wind = 0;

  const fx = Math.sin(p.yaw), fz = Math.cos(p.yaw);
  const hSpeed = p.speed * Math.cos(p.pitch);
  const prevZ = p.z;
  p.x += fx * hSpeed * dt + S.wind * dt * 0.35;
  p.z += fz * hSpeed * dt;
  p.y += Math.sin(p.pitch) * p.speed * dt;
  // Gentle sink when too slow to stay airborne.
  if (p.speed < 26 && p.y > terrainH(p.x, p.z) + 1) p.y -= (26 - p.speed) * 0.35 * dt;

  const ground = terrainH(p.x, p.z);
  const onRunway = p.z >= RUNWAY.z0 && p.z <= RUNWAY.z1 && Math.abs(p.x) < RUNWAY.half;

  // Ring crossing: plane passes the ring's z-plane while flying forward.
  const r = rings[S.nextRing];
  if (r && S.phase === 'course') {
    const crossed = (prevZ < r.z && p.z >= r.z) || (prevZ > r.z && p.z <= r.z);
    if (crossed) {
      const dx = p.x - r.x, dy = p.y - r.y;
      if (Math.hypot(dx, dy) < r.r) {
        r.passed = true; S.nextRing++;
        S.score += 100; S.timeLeft = Math.min(240, S.timeLeft + 5);
        S.flash = 'RING! +100'; S.flashT = 1.4; AudioSys.ring();
        spawnBurst(r.x, r.y, r.z, '#ffd34d');
        if (S.nextRing >= RING_COUNT) {
          S.phase = 'return';
          S.flash = 'COURSE CLEAR — LAND ON THE RUNWAY'; S.flashT = 3;
        }
      } else if (Math.abs(p.z - r.z) < 40 && !r.missed) {
        r.missed = true; S.flash = 'RING MISSED'; S.flashT = 1.2;
      }
    }
  }

  // Landing: gentle touchdown inside the strip while returning.
  if (S.phase === 'return' && onRunway && p.y <= 1.2 && p.speed < 48 && p.speed > 8 && Math.abs(p.pitch) < 0.25) {
    return land();
  }

  // Terrain / water contact.
  if (p.y <= ground + 0.6) {
    if (onRunway && p.speed < 48 && Math.abs(p.pitch) < 0.3 && S.phase === 'return') return land();
    if (p.y <= ground + 0.6 && S.invuln <= 0) return crash();
    p.y = ground + 0.6;
  }
  if (S.invuln > 0) S.invuln -= dt;
  if (S.flashT > 0) S.flashT -= dt;

  // Particles.
  for (let i = S.particles.length - 1; i >= 0; i--) {
    const pt = S.particles[i];
    pt.life -= dt; pt.x += pt.vx * dt; pt.y += pt.vy * dt; pt.z += pt.vz * dt;
    if (pt.life <= 0) S.particles.splice(i, 1);
  }

  // Camera chases from behind and above, smoothing the ride.
  const cx = p.x - Math.sin(p.yaw) * 24, cz = p.z - Math.cos(p.yaw) * 24;
  const cy = p.y + 6.5 + p.speed * 0.008;
  const k = clamp(dt * 6, 0, 1);
  S.cam.x = lerp(S.cam.x, cx, k); S.cam.y = lerp(S.cam.y, cy, k); S.cam.z = lerp(S.cam.z, cz, k);
  S.cam.yaw = angLerp(S.cam.yaw, p.yaw, clamp(dt * 4, 0, 1));

  AudioSys.engine(p.throttle, clamp(p.speed / 150, 0, 1));
}

function spawnBurst(x, y, z, color) {
  for (let i = 0; i < 26; i++) {
    const a = rng() * Math.PI * 2, b = rng() * Math.PI - Math.PI / 2;
    const sp = 18 + rng() * 30;
    S.particles.push({
      x, y, z, color,
      vx: Math.cos(a) * Math.cos(b) * sp, vy: Math.sin(b) * sp, vz: Math.sin(a) * Math.cos(b) * sp,
      life: 0.6 + rng() * 0.7,
    });
  }
}

function crash() {
  AudioSys.crash();
  spawnBurst(S.plane.x, S.plane.y, S.plane.z, '#ff7a3c');
  spawnBurst(S.plane.x, S.plane.y, S.plane.z, '#ffd34d');
  S.lives--;
  S.mode = 'crashed'; S.crashT = 0;
  if (S.lives <= 0) { saveBest(); }
}
function land() {
  S.score += 500 + Math.round(S.timeLeft) * 10;
  saveBest();
  S.mode = 'win'; S.t = 0;
  AudioSys.click();
}
function gameOver(why) {
  saveBest();
  S.mode = 'gameover'; S.t = 0; S.gameoverWhy = why;
}

// ---------- projection ----------
const FOCAL = (H / 2) / Math.tan(34 * Math.PI / 180);
function project(x, y, z) {
  const cam = S.cam;
  const dx = x - cam.x, dy = y - cam.y, dz = z - cam.z;
  const s = Math.sin(cam.yaw), c = Math.cos(cam.yaw);
  const cz = dx * s + dz * c;
  if (cz < 3) return null;
  const cx = dx * c - dz * s;
  const cy = dy;
  let sx = W / 2 + (cx / cz) * FOCAL;
  let sy = H / 2 - (cy / cz) * FOCAL;
  // Camera roll follows the plane's bank, so the world tilts as you turn.
  const roll = -S.plane.bank * 0.45;
  if (roll !== 0) {
    const rx = sx - W / 2, ry = sy - H / 2;
    const cr = Math.cos(roll), sr = Math.sin(roll);
    sx = W / 2 + rx * cr - ry * sr;
    sy = H / 2 + rx * sr + ry * cr;
  }
  return { x: sx, y: sy, d: cz, s: FOCAL / cz };
}

// ---------- sky ----------
function drawSky() {
  const g = ctx.createLinearGradient(0, 0, 0, H);
  if (golden > 0.5) {
    g.addColorStop(0, '#3d4378'); g.addColorStop(0.45, '#c96a4e'); g.addColorStop(0.62, '#ffb26b'); g.addColorStop(1, '#7a5a6e');
  } else {
    g.addColorStop(0, '#2b6cc4'); g.addColorStop(0.5, '#7fb8e8'); g.addColorStop(0.68, '#cfe9f5'); g.addColorStop(1, '#dceef7');
  }
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
  // Sun with glow.
  const sunX = W * 0.78, sunY = golden > 0.5 ? H * 0.22 : H * 0.15;
  const glow = ctx.createRadialGradient(sunX, sunY, 4, sunX, sunY, 130);
  const sunCol = golden > 0.5 ? '255,170,80' : '255,244,200';
  glow.addColorStop(0, 'rgba(' + sunCol + ',0.95)');
  glow.addColorStop(0.25, 'rgba(' + sunCol + ',0.45)');
  glow.addColorStop(1, 'rgba(' + sunCol + ',0)');
  ctx.fillStyle = glow;
  ctx.fillRect(sunX - 140, sunY - 140, 280, 280);
  ctx.fillStyle = golden > 0.5 ? '#ffd9a0' : '#fff6c8';
  ctx.beginPath(); ctx.arc(sunX, sunY, golden > 0.5 ? 30 : 24, 0, Math.PI * 2); ctx.fill();
  // Far mountain ridges on the horizon.
  for (let layer = 0; layer < 2; layer++) {
    const base = H / 2 - 6 - layer * 26;
    ctx.beginPath(); ctx.moveTo(0, H);
    for (let sx = 0; sx <= W; sx += 32) {
      const n = fbm(sx * 0.006 + layer * 9.1 + S.cam.yaw * 1.4, layer * 3.7);
      ctx.lineTo(sx, base - (n * 0.5 + 0.5) * (26 + layer * 30));
    }
    ctx.lineTo(W, H); ctx.closePath();
    ctx.fillStyle = layer === 0 ? 'rgba(74,92,140,0.55)' : 'rgba(52,66,110,0.75)';
    ctx.fill();
  }
}

// ---------- clouds ----------
const clouds = [];
for (let i = 0; i < 26; i++) {
  clouds.push({
    x: (rng() * 2 - 1) * 1100,
    y: 250 + rng() * 170,
    z: rng() * COURSE_LEN,
    s: 45 + rng() * 90,
  });
}
function drawClouds(dt) {
  for (const c of clouds) {
    c.x += dt * 1.5;
    if (c.x > 1200) c.x = -1200;
    const p = project(c.x, c.y, c.z);
    if (!p) continue;
    const r = c.s * p.s;
    if (r < 2) continue;
    ctx.fillStyle = 'rgba(255,255,255,0.82)';
    ctx.beginPath();
    ctx.ellipse(p.x, p.y, r * 1.6, r * 0.55, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath();
    ctx.ellipse(p.x - r * 0.7, p.y + r * 0.12, r * 0.9, r * 0.42, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath();
    ctx.ellipse(p.x + r * 0.8, p.y + r * 0.14, r * 1.0, r * 0.45, 0, 0, Math.PI * 2); ctx.fill();
  }
}

// ---------- terrain ----------
function patchColor(x, z) {
  const px = Math.floor(x / 170), pz = Math.floor(z / 170);
  const h = hash2(px * 3 + 11, pz * 5 + 7);
  if (h < 0.22) return [201, 180, 88];    // wheat
  if (h < 0.48) return [79, 158, 68];     // green
  if (h < 0.68) return [92, 184, 79];     // light green
  if (h < 0.85) return [62, 138, 60];     // dark green
  return [140, 170, 80];                  // meadow
}
function terrainColor(x, z, h, quad) {
  // quad = world-space bounds of the terrain quad being painted. The runway
  // (32 m wide) and road (12 m) are narrower than one 50 m quad, so features
  // are tested by bounding-box overlap, not by the quad centre alone —
  // otherwise the strip would almost never land on a quad centre.
  const q = quad || { x0: x, x1: x, z0: z, z1: z };
  // Runway strip (grey, white centre dashes + threshold bars).
  if (q.z1 >= RUNWAY.z0 && q.z0 <= RUNWAY.z1 && q.x1 >= -RUNWAY.half && q.x0 <= RUNWAY.half) {
    if (q.x1 >= -3 && q.x0 <= 3 && (Math.floor(((q.z0 + q.z1) / 2) / 50) % 2) === 0) return [235, 235, 235];
    if (((q.z0 < 40 && q.z1 > 0) || (q.z0 < 640 && q.z1 > 600)) && (q.x1 < -10 || q.x0 > 10)) return [240, 240, 240];
    return [88, 88, 92];
  }
  const rx = riverX(z);
  if (q.x1 >= rx - 22 && q.x0 <= rx + 22 && h < 3.2) return [47, 127, 196];
  const dx = roadX(z);
  if (q.x1 >= dx - 6 && q.x0 <= dx + 6) return [58, 58, 60];
  const [r, g, b] = patchColor(x, z);
  // Height tints: rock, then snow on the high edges.
  let cr = r, cg = g, cb = b;
  if (h > 60) {
    const k = clamp((h - 60) / 90, 0, 1);
    cr = lerp(cr, 125, k); cg = lerp(cg, 116, k); cb = lerp(cb, 104, k);
  }
  if (h > 165) {
    const k = clamp((h - 165) / 40, 0, 1);
    cr = lerp(cr, 232, k); cg = lerp(cg, 238, k); cb = lerp(cb, 242, k);
  }
  // Simple slope shading: darker on the far side of bumps.
  const slope = (terrainH(x + 24, z) - h) / 24;
  const shade = clamp(1 - slope * 1.4, 0.72, 1.12);
  return [Math.round(cr * shade), Math.round(cg * shade), Math.round(cb * shade)];
}
function drawTerrain() {
  // Grid built in camera space (forward/lateral), so the ground renders
  // correctly whatever heading the plane flies — including the return leg
  // back toward the runway, when "ahead" is -z.
  const cam = S.cam;
  const fx = Math.sin(cam.yaw), fz = Math.cos(cam.yaw);
  const rx = Math.cos(cam.yaw), rz = -Math.sin(cam.yaw);
  const STEP = 50, HALF = 750;
  for (let d = 1500; d > -80; d -= STEP) {
    const d1 = d - STEP;
    for (let l = -HALF; l < HALF; l += STEP) {
      const cs = [];
      let ok = true;
      const pts = [[d, l], [d, l + STEP], [d1, l], [d1, l + STEP]];
      let qx0 = 1e9, qx1 = -1e9, qz0 = 1e9, qz1 = -1e9;
      for (const [dd, ll] of pts) {
        const wx = cam.x + fx * dd + rx * ll, wz = cam.z + fz * dd + rz * ll;
        qx0 = Math.min(qx0, wx); qx1 = Math.max(qx1, wx);
        qz0 = Math.min(qz0, wz); qz1 = Math.max(qz1, wz);
        const h = terrainH(wx, wz);
        const p = project(wx, h, wz);
        if (!p) { ok = false; break; }
        cs.push(p);
      }
      if (!ok) continue;
      const mcx = cam.x + fx * (d - STEP / 2) + rx * (l + STEP / 2);
      const mcz = cam.z + fz * (d - STEP / 2) + rz * (l + STEP / 2);
      const hm = terrainH(mcx, mcz);
      const [r, g, b] = terrainColor(mcx, mcz, hm, { x0: qx0, x1: qx1, z0: qz0, z1: qz1 });
      const haze = clamp((cs[0].d - 500) / 1300, 0, 0.65);
      const hr = Math.round(lerp(r, 190, haze)), hg = Math.round(lerp(g, 215, haze)), hb = Math.round(lerp(b, 235, haze));
      ctx.fillStyle = 'rgb(' + hr + ',' + hg + ',' + hb + ')';
      ctx.beginPath();
      ctx.moveTo(cs[0].x, cs[0].y); ctx.lineTo(cs[1].x, cs[1].y); ctx.lineTo(cs[3].x, cs[3].y); ctx.lineTo(cs[2].x, cs[2].y);
      ctx.closePath(); ctx.fill();
    }
  }
}

// ---------- rings ----------
function drawRing(r, i) {
  const N = 22;
  let first = null;
  ctx.beginPath();
  for (let k = 0; k <= N; k++) {
    const a = (k / N) * Math.PI * 2;
    const p = project(r.x + Math.cos(a) * r.r, r.y + Math.sin(a) * r.r, r.z);
    if (!p) { first = null; continue; }
    if (k === 0 || !first) { ctx.moveTo(p.x, p.y); first = p; }
    else ctx.lineTo(p.x, p.y);
  }
  const isNext = i === S.nextRing && S.phase === 'course';
  const col = r.passed ? '#39d353' : r.missed ? '#e5484d' : isNext ? '#ffd34d' : '#35d0ff';
  ctx.strokeStyle = col;
  ctx.lineWidth = isNext ? 7 : 4;
  ctx.shadowColor = col; ctx.shadowBlur = isNext ? 22 : 0;
  ctx.stroke();
  ctx.shadowBlur = 0;
  // Inner chevron ring for depth.
  if (isNext) {
    ctx.beginPath();
    for (let k = 0; k <= N; k++) {
      const a = (k / N) * Math.PI * 2;
      const p = project(r.x + Math.cos(a) * r.r * 0.55, r.y + Math.sin(a) * r.r * 0.55, r.z);
      if (!p) continue;
      if (k === 0) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y);
    }
    ctx.strokeStyle = 'rgba(255,211,77,0.55)'; ctx.lineWidth = 2; ctx.stroke();
  }
}
function drawGuideDots() {
  const r = rings[S.nextRing];
  if (!r || S.phase !== 'course') return;
  const p = S.plane;
  ctx.fillStyle = 'rgba(255,211,77,0.9)';
  for (let i = 1; i <= 6; i++) {
    const t = i / 7;
    const pt = project(lerp(p.x, r.x, t), lerp(p.y, r.y, t), lerp(p.z, r.z, t));
    if (!pt) continue;
    ctx.beginPath(); ctx.arc(pt.x, pt.y, 2.5 + pt.s * 2, 0, Math.PI * 2); ctx.fill();
  }
}
function drawParticles() {
  for (const pt of S.particles) {
    const p = project(pt.x, pt.y, pt.z);
    if (!p) continue;
    ctx.globalAlpha = clamp(pt.life, 0, 1);
    ctx.fillStyle = pt.color;
    ctx.beginPath(); ctx.arc(p.x, p.y, 3 + p.s * 4, 0, Math.PI * 2); ctx.fill();
  }
  ctx.globalAlpha = 1;
}

// ---------- the plane (drawn in screen space, chase view) ----------
function drawPlaneShadow() {
  const p = S.plane;
  const g = terrainH(p.x, p.z);
  if (p.y - g > 220) return;
  const sp = project(p.x, g + 0.8, p.z);
  if (!sp) return;
  ctx.fillStyle = 'rgba(10,20,30,0.28)';
  ctx.beginPath();
  ctx.ellipse(sp.x, sp.y, 30 * sp.s, 9 * sp.s, 0, 0, Math.PI * 2);
  ctx.fill();
}
function drawPlane() {
  const px = W / 2, py = H * 0.60 + S.plane.pitch * 90;
  const blink = (S.t % 1.2) < 0.15;
  ctx.save();
  ctx.translate(px, py);
  ctx.rotate(S.plane.bank * 0.85);
  const s = 1.05;
  ctx.scale(s, s);
  // Prop blur disc at the nose (top of the drawing, forward = up-screen).
  ctx.fillStyle = 'rgba(220,230,240,0.28)';
  ctx.beginPath(); ctx.ellipse(0, -118, 13, 46, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = 'rgba(200,210,225,0.35)';
  ctx.beginPath(); ctx.ellipse(0, -118, 5, 40, 0, 0, Math.PI * 2); ctx.fill();
  // Main wings (swept back slightly).
  ctx.fillStyle = '#e8dcc3';
  ctx.beginPath();
  ctx.moveTo(-14, -52); ctx.lineTo(-168, 6); ctx.lineTo(-168, 22); ctx.lineTo(-16, -30);
  ctx.lineTo(16, -30); ctx.lineTo(168, 22); ctx.lineTo(168, 6); ctx.lineTo(14, -52);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#b7a67f'; ctx.lineWidth = 2; ctx.stroke();
  // Wing stripe.
  ctx.fillStyle = '#1f8a8c';
  ctx.fillRect(-168, 8, 336, 7);
  // Fuselage: tapered body, nose at the top.
  const fg = ctx.createLinearGradient(-16, 70, 16, -118);
  fg.addColorStop(0, '#d9c9a3'); fg.addColorStop(0.55, '#f4ead2'); fg.addColorStop(1, '#fff6df');
  ctx.fillStyle = fg;
  ctx.beginPath();
  ctx.moveTo(-15, 74); ctx.quadraticCurveTo(-19, 10, -11, -96);
  ctx.quadraticCurveTo(-7, -118, 0, -120); ctx.quadraticCurveTo(7, -118, 11, -96);
  ctx.quadraticCurveTo(19, 10, 15, 74); ctx.quadraticCurveTo(0, 84, -15, 74);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#a08c5f'; ctx.lineWidth = 1.5; ctx.stroke();
  // Teal cheatline along the fuselage.
  ctx.fillStyle = '#1f8a8c';
  ctx.beginPath();
  ctx.moveTo(-13, 30); ctx.quadraticCurveTo(-15, -20, -9, -80); ctx.lineTo(-6, -80);
  ctx.quadraticCurveTo(-11, -20, -9, 30); ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(13, 30); ctx.quadraticCurveTo(15, -20, 9, -80); ctx.lineTo(6, -80);
  ctx.quadraticCurveTo(11, -20, 9, 30); ctx.closePath(); ctx.fill();
  // Canopy (lit glass).
  const cg = ctx.createLinearGradient(0, -88, 0, -52);
  cg.addColorStop(0, '#bfe6ff'); cg.addColorStop(1, '#2f7fc4');
  ctx.fillStyle = cg;
  ctx.beginPath(); ctx.ellipse(0, -70, 8.5, 17, 0, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = '#5d4f2f'; ctx.lineWidth = 1.5; ctx.stroke();
  // Tail: vertical fin + horizontal stabilizer.
  ctx.fillStyle = '#ff7a3c';
  ctx.beginPath();
  ctx.moveTo(-9, 66); ctx.lineTo(-11, 108); ctx.lineTo(11, 108); ctx.lineTo(9, 66); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#f4ead2';
  ctx.beginPath();
  ctx.moveTo(-52, 84); ctx.lineTo(52, 84); ctx.lineTo(46, 96); ctx.lineTo(-46, 96); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#a08c5f'; ctx.lineWidth = 1.5; ctx.stroke();
  // Registration on the fin.
  ctx.fillStyle = '#12333a';
  ctx.font = 'bold 11px monospace'; ctx.textAlign = 'center';
  ctx.fillText('SC-7', 0, 100);
  // Nav lights: red port, green starboard, white strobe on the tail.
  ctx.fillStyle = '#ff3b30'; ctx.beginPath(); ctx.arc(-168, 14, 4, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#34d17b'; ctx.beginPath(); ctx.arc(168, 14, 4, 0, Math.PI * 2); ctx.fill();
  if (blink) {
    ctx.fillStyle = '#ffffff'; ctx.beginPath(); ctx.arc(0, 110, 4, 0, Math.PI * 2); ctx.fill();
  }
  // Landing gear when slow or on final.
  if (S.phase === 'return' || S.plane.speed < 45) {
    ctx.strokeStyle = '#4a3f28'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(-12, 62); ctx.lineTo(-18, 82); ctx.moveTo(12, 62); ctx.lineTo(18, 82); ctx.stroke();
    ctx.fillStyle = '#222';
    ctx.beginPath(); ctx.arc(-18, 84, 5, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(18, 84, 5, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();
}

// ---------- HUD ----------
function panel(x, y, w, h) {
  ctx.fillStyle = 'rgba(8,16,30,0.62)';
  ctx.strokeStyle = 'rgba(120,200,255,0.35)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  const r = 10;
  ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y); ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h - r); ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
  ctx.lineTo(x + r, y + h); ctx.arcTo(x, y + h, x, y + h - r, r);
  ctx.lineTo(x, y + r); ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath(); ctx.fill(); ctx.stroke();
}
function hudText(txt, x, y, size, col, align) {
  ctx.fillStyle = col || '#dff3ff';
  ctx.font = 'bold ' + size + 'px ui-monospace, Menlo, Consolas, monospace';
  ctx.textAlign = align || 'left'; ctx.textBaseline = 'alphabetic';
  ctx.fillText(txt, x, y);
}
function fmt(n, d) { return n.toFixed(d === undefined ? 0 : d); }
function drawHUD() {
  const p = S.plane;
  const altFt = Math.max(0, p.y * 3.281);
  const spdKt = p.speed * 1.944;
  const hdg = ((p.yaw * 180 / Math.PI) % 360 + 360) % 360;
  const vsFpm = Math.sin(p.pitch) * p.speed * 196.85;

  // Top-left: instruments.
  panel(18, 16, 250, 108);
  hudText('ALT', 34, 44, 13, '#7fc8ff');
  hudText(fmt(altFt) + ' FT', 120, 44, 18);
  hudText('SPD', 34, 72, 13, '#7fc8ff');
  hudText(fmt(spdKt) + ' KT', 120, 72, 18);
  hudText('HDG', 34, 100, 13, '#7fc8ff');
  hudText(fmt(hdg, 0).padStart(3, '0') + '°', 120, 100, 18);
  hudText('V/S ' + (vsFpm >= 0 ? '+' : '') + fmt(vsFpm) + ' FPM', 180, 116, 11, '#9fb8cc');

  // Top-centre: compass tape.
  panel(W / 2 - 190, 16, 380, 46);
  const labels = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  ctx.save();
  ctx.beginPath(); ctx.rect(W / 2 - 190, 16, 380, 46); ctx.clip();
  for (let d = -60; d <= 60; d += 5) {
    const deg = Math.round(hdg + d);
    const x = W / 2 + d * 3;
    const norm = ((deg % 360) + 360) % 360;
    const isCard = norm % 45 === 0;
    ctx.strokeStyle = isCard ? '#ffd34d' : 'rgba(160,210,255,0.7)';
    ctx.lineWidth = isCard ? 2 : 1;
    ctx.beginPath(); ctx.moveTo(x, 26); ctx.lineTo(x, isCard ? 46 : 38); ctx.stroke();
    if (isCard) hudText(labels[Math.round(norm / 45) % 8], x, 58, 12, '#ffd34d', 'center');
    else if (norm % 15 === 0) hudText(String(norm).padStart(3, '0'), x, 58, 10, '#9fb8cc', 'center');
  }
  ctx.restore();
  ctx.fillStyle = '#ffd34d';
  ctx.beginPath(); ctx.moveTo(W / 2 - 7, 16); ctx.lineTo(W / 2 + 7, 16); ctx.lineTo(W / 2, 26); ctx.closePath(); ctx.fill();

  // Top-right: score, rings, time, lives.
  panel(W - 268, 16, 250, 108);
  hudText('SCORE', W - 252, 44, 13, '#7fc8ff');
  hudText(String(S.score), W - 34, 44, 20, '#ffd34d', 'right');
  hudText('RINGS', W - 252, 72, 13, '#7fc8ff');
  hudText(S.nextRing + '/' + RING_COUNT, W - 34, 72, 18, '#dff3ff', 'right');
  const tmm = Math.floor(S.timeLeft / 60), tss = Math.floor(S.timeLeft % 60);
  hudText('TIME', W - 252, 100, 13, '#7fc8ff');
  hudText(tmm + ':' + String(tss).padStart(2, '0'), W - 34, 100, 18, S.timeLeft < 30 ? '#ff6b5e' : '#dff3ff', 'right');
  for (let i = 0; i < 3; i++) {
    ctx.fillStyle = i < S.lives ? '#ff7a3c' : 'rgba(255,255,255,0.18)';
    ctx.beginPath();
    ctx.moveTo(W - 252 + i * 26, 116); ctx.lineTo(W - 244 + i * 26, 108); ctx.lineTo(W - 236 + i * 26, 116);
    ctx.closePath(); ctx.fill();
  }

  // Bottom-left: attitude indicator.
  const ax = 78, ay = H - 78, ar = 46;
  ctx.save();
  ctx.beginPath(); ctx.arc(ax, ay, ar, 0, Math.PI * 2); ctx.clip();
  ctx.translate(ax, ay); ctx.rotate(-p.bank);
  ctx.translate(0, p.pitch * 90);
  ctx.fillStyle = '#3a7bd5'; ctx.fillRect(-ar - 4, -ar - 60, ar * 2 + 8, ar + 60);
  ctx.fillStyle = '#7a5230'; ctx.fillRect(-ar - 4, 0, ar * 2 + 8, ar + 60);
  ctx.fillStyle = '#fff'; ctx.fillRect(-ar - 4, -1.5, ar * 2 + 8, 3);
  ctx.restore();
  ctx.strokeStyle = 'rgba(160,210,255,0.8)'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(ax, ay, ar, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = '#ffd34d';
  ctx.beginPath(); ctx.moveTo(ax - 16, ay); ctx.lineTo(ax - 4, ay); ctx.lineTo(ax, ay + 5); ctx.lineTo(ax + 4, ay); ctx.lineTo(ax + 16, ay); ctx.lineTo(ax + 4, ay + 3); ctx.lineTo(ax - 4, ay + 3); ctx.closePath(); ctx.fill();
  hudText('ATTITUDE', ax - 34, ay + ar + 18, 10, '#9fb8cc', 'left');

  // Bottom-right: throttle bar.
  panel(W - 128, H - 108, 110, 92);
  hudText('THR', W - 112, H - 84, 11, '#7fc8ff');
  const th = p.throttle;
  ctx.fillStyle = 'rgba(255,255,255,0.15)';
  ctx.fillRect(W - 112, H - 74, 78, 12);
  ctx.fillStyle = th > 0.85 ? '#ff7a3c' : '#35d0ff';
  ctx.fillRect(W - 112, H - 74, 78 * th, 12);
  hudText(fmt(th * 100) + '%', W - 112, H - 46, 13);
  hudText('W/S THROTTLE', W - 112, H - 28, 9, '#9fb8cc');

  // Centre crosshair + next-ring arrow.
  ctx.strokeStyle = 'rgba(255,255,255,0.75)'; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.arc(W / 2, H * 0.60, 10, 0, Math.PI * 2); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(W / 2 - 16, H * 0.60); ctx.lineTo(W / 2 - 8, H * 0.60); ctx.moveTo(W / 2 + 8, H * 0.60); ctx.lineTo(W / 2 + 16, H * 0.60); ctx.stroke();

  const target = S.phase === 'course' ? rings[S.nextRing] : { x: 0, y: 0, z: 320 };
  if (target) {
    const tp = project(target.x, target.y, target.z);
    const label = S.phase === 'course' ? 'RING ' + (S.nextRing + 1) : 'RUNWAY';
    if (!tp || tp.x < 40 || tp.x > W - 40 || tp.y < 60 || tp.y > H - 60) {
      // Off-screen: point an arrow at the screen edge.
      const dx = target.x - p.x, dz = target.z - p.z;
      const ang = Math.atan2(dx, dz) - p.yaw;
      const ex = W / 2 + Math.sin(ang) * 260, ey = H * 0.60 - Math.cos(ang) * 200;
      const cxp = clamp(ex, 60, W - 60), cyp = clamp(ey, 80, H - 80);
      ctx.save(); ctx.translate(cxp, cyp); ctx.rotate(Math.atan2(ex - W / 2, -(ey - H * 0.60)) * -1 + Math.PI);
      ctx.fillStyle = S.phase === 'course' ? '#ffd34d' : '#39d353';
      ctx.beginPath(); ctx.moveTo(0, -16); ctx.lineTo(12, 10); ctx.lineTo(-12, 10); ctx.closePath(); ctx.fill();
      ctx.restore();
      hudText(label, cxp, cyp + 30, 12, '#ffd34d', 'center');
    } else {
      ctx.strokeStyle = S.phase === 'course' ? 'rgba(255,211,77,0.9)' : 'rgba(57,211,83,0.9)';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(tp.x, tp.y, 18, 0, Math.PI * 2); ctx.stroke();
      hudText(label, tp.x, tp.y - 26, 12, '#ffd34d', 'center');
    }
  }

  // Warnings.
  const ground = terrainH(p.x, p.z);
  if (S.mode === 'playing' && p.y - ground < 25 && p.y > ground + 1 && Math.sin(p.pitch) < 0.05) {
    if (Math.floor(S.t * 4) % 2 === 0) {
      hudText('⚠ TERRAIN — PULL UP', W / 2, 150, 26, '#ff6b5e', 'center');
    }
  }
  if (S.mode === 'playing' && p.speed < 26 && p.y > ground + 2) {
    hudText('STALL — ADD THROTTLE (W)', W / 2, 182, 16, '#ffb26b', 'center');
  }
  if (S.phase === 'return' && S.mode === 'playing') {
    hudText('COURSE CLEAR — LAND ON THE RUNWAY', W / 2, 118, 15, '#39d353', 'center');
  }
  if (S.flashT > 0) {
    ctx.globalAlpha = clamp(S.flashT, 0, 1);
    hudText(S.flash, W / 2, 210, 24, '#ffd34d', 'center');
    ctx.globalAlpha = 1;
  }
  if (S.invuln > 0 && S.mode === 'playing') {
    hudText('RESPAWNED — FLY SAFE', W / 2, 240, 14, '#9fb8cc', 'center');
  }
  if (S.muted) hudText('MUTED (M)', W - 20, H - 130, 11, '#9fb8cc', 'right');
}

// ---------- screens ----------
function dimScreen() {
  ctx.fillStyle = 'rgba(6,10,24,0.62)'; ctx.fillRect(0, 0, W, H);
}
function bigTitle(txt, y, size, col) {
  ctx.fillStyle = col || '#ffffff';
  ctx.font = '900 ' + size + 'px ui-monospace, Menlo, Consolas, monospace';
  ctx.textAlign = 'center';
  ctx.fillText(txt, W / 2, y);
}
function drawTitle() {
  dimScreen();
  bigTitle('SKY COURIER', 210, 72, '#ffffff');
  hudText('— RING RUN —', W / 2, 250, 22, '#ffd34d', 'center');
  hudText('Fly the 12 rings over the valley, then bring her home.', W / 2, 292, 17, '#dff3ff', 'center');
  hudText('Arrows pitch & bank · W/S throttle · mouse steers · P pause · M mute', W / 2, 330, 15, '#9fb8cc', 'center');
  if (S.best > 0) hudText('BEST SCORE  ' + S.best, W / 2, 368, 16, '#39d353', 'center');
  const pulse = 0.6 + 0.4 * Math.sin(S.t * 3);
  ctx.globalAlpha = pulse;
  bigTitle('CLICK OR PRESS ENTER TO FLY', 450, 26, '#ffd34d');
  ctx.globalAlpha = 1;
  hudText('A tiny original flight game — no downloads, no network, just you and the valley.', W / 2, 520, 13, '#7d93a8', 'center');
}
function drawEnd(why, title, col) {
  dimScreen();
  bigTitle(title, 190, 54, col || '#ffffff');
  if (why) hudText(why, W / 2, 232, 16, '#9fb8cc', 'center');
  const rows = [
    ['SCORE', String(S.score)],
    ['RINGS', S.nextRing + ' / ' + RING_COUNT],
    ['BEST', String(S.best)],
  ];
  let y = 300;
  for (const [k, v] of rows) {
    hudText(k, W / 2 - 130, y, 16, '#7fc8ff');
    hudText(v, W / 2 + 130, y, 18, '#ffd34d', 'right');
    y += 36;
  }
  if (S.mode === 'win') {
    hudText('Rings 12 × 100  +  landing 500  +  time bonus', W / 2, y + 8, 14, '#9fb8cc', 'center');
  }
  bigTitle('PRESS R TO FLY AGAIN', 520, 22, '#ffd34d');
}
function drawPaused() {
  dimScreen();
  bigTitle('PAUSED', 330, 56, '#ffffff');
  hudText('Press P to keep flying', W / 2, 380, 16, '#9fb8cc', 'center');
}
function drawCrashed() {
  hudText('CRASHED!', W / 2, 300, 44, '#ff6b5e', 'center');
  hudText(S.lives > 0 ? 'Lives left: ' + S.lives + ' — respawning…' : 'No lives left.', W / 2, 350, 17, '#dff3ff', 'center');
}

// ---------- vignette ----------
function drawVignette() {
  const g = ctx.createRadialGradient(W / 2, H / 2, H * 0.45, W / 2, H / 2, H * 0.95);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,10,0.28)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
}

// ---------- main loop ----------
let last = 0;
function frame(ts) {
  const dt = Math.min(0.05, (ts - last) / 1000 || 0.016);
  last = ts;
  S.t += dt;

  if (S.mode === 'playing') update(dt);
  else if (S.mode === 'crashed') {
    S.crashT += dt;
    if (S.crashT > 2) {
      if (S.lives <= 0) gameOver('OUT OF LIVES');
      else { resetPlane(false); S.mode = 'playing'; }
    }
  } else if (S.mode === 'title') {
    // Attract mode: slow glide over the valley for the menu backdrop.
    const az = (S.t * 22) % COURSE_LEN;
    S.cam.x = courseX(az) + 40; S.cam.y = terrainH(courseX(az), az) + 95; S.cam.z = az - 30; S.cam.yaw = 0;
    S.plane.bank = Math.sin(S.t * 0.4) * 0.12;
  }

  drawSky();
  drawClouds(S.mode === 'playing' ? dt : dt * 0.3);
  drawTerrain();
  if (S.mode !== 'title') {
    for (let i = 0; i < rings.length; i++) {
      if (rings[i].z > S.cam.z - 80 && rings[i].z < S.cam.z + 1700) drawRing(rings[i], i);
    }
    drawGuideDots();
    drawParticles();
    drawPlaneShadow();
    drawPlane();
  }
  if (S.mode === 'playing' || S.mode === 'paused' || S.mode === 'crashed') drawHUD();
  if (S.mode === 'title') drawTitle();
  else if (S.mode === 'paused') drawPaused();
  else if (S.mode === 'crashed') drawCrashed();
  else if (S.mode === 'gameover') drawEnd(S.gameoverWhy, 'FLIGHT OVER', '#ff6b5e');
  else if (S.mode === 'win') drawEnd('You flew all 12 rings and greased the landing.', 'COURSE COMPLETE', '#39d353');
  drawVignette();

  if (!window.__shotDone) requestAnimationFrame(frame);
}

// ---------- staged screenshot scenes (?shot=) & self-test (?selftest=1) ----------
function setupShot(name) {
  S.mode = 'shot';
  golden = name === 'landing' ? 1 : 0;
  if (name === 'title') {
    S.mode = 'title';
    S.t = 6; // a later attract frame: more terrain in view
    const az = 2400;
    S.cam.x = courseX(az) + 40; S.cam.y = terrainH(courseX(az), az) + 95; S.cam.z = az - 30; S.cam.yaw = 0;
    return;
  }
  // All flying shots share one honest setup: real playing state, frozen mid-flight.
  S.mode = 'playing';
  resetGame();
  S.invuln = 0; // no "RESPAWNED" banner in a screenshot
  if (name === 'ring') {
    // Mid-course: ring 4 ahead and clearly in frame, offset so it is not
    // hidden behind the plane, river and fields alongside.
    S.nextRing = 3;
    rings[0].passed = rings[1].passed = rings[2].passed = true;
    S.score = 300;
    const r = rings[3];
    S.plane.x = r.x - 85; S.plane.y = r.y - 6; S.plane.z = r.z - 180;
    S.plane.yaw = Math.atan2(r.x - S.plane.x, r.z - S.plane.z);
    S.plane.speed = 85; S.plane.throttle = 0.7; S.plane.bank = 0.12; S.plane.pitch = 0.02;
    S.timeLeft = 121;
  } else if (name === 'low') {
    // Low pass near the river, ring 7 ahead and in frame.
    S.nextRing = 6;
    for (let i = 0; i < 6; i++) rings[i].passed = true;
    S.score = 600;
    const r = rings[6];
    S.plane.x = r.x - 45; S.plane.y = r.y + 2; S.plane.z = r.z - 260;
    S.plane.yaw = Math.atan2(r.x - S.plane.x, r.z - S.plane.z);
    S.plane.speed = 96; S.plane.throttle = 0.78; S.plane.bank = -0.18; S.plane.pitch = -0.02;
    S.timeLeft = 98;
  } else if (name === 'landing') {
    // Final approach: gear down, runway dead ahead, golden light.
    S.phase = 'return';
    S.nextRing = RING_COUNT;
    for (const rg of rings) rg.passed = true;
    S.score = 1200;
    S.plane.x = 120; S.plane.y = 32; S.plane.z = 1050;
    S.plane.yaw = Math.PI + 0.10; // flying back toward -z, converging on the strip
    S.plane.speed = 52; S.plane.throttle = 0.32; S.plane.bank = 0.05; S.plane.pitch = -0.08;
    S.timeLeft = 64;
  }
  // Settle the camera once, then freeze the frame for the screenshot.
  updateCameraOnly();
  window.__shotDone = true; // render exactly one frame after this setup
}
function updateCameraOnly() {
  const p = S.plane;
  S.cam.x = p.x - Math.sin(p.yaw) * 24;
  S.cam.z = p.z - Math.cos(p.yaw) * 24;
  S.cam.y = p.y + 6.5 + p.speed * 0.008;
  S.cam.yaw = p.yaw;
}

function runSelfTest() {
  const out = [];
  const ok = (name, cond, extra) => out.push((cond ? 'PASS' : 'FAIL') + ' ' + name + (extra !== undefined ? ' — ' + extra : ''));
  try {
    // Terrain sanity: finite, in range, runway flat.
    let bad = 0, mn = 1e9, mx = -1e9;
    for (let i = 0; i < 2000; i++) {
      const h = terrainH((rng() * 2 - 1) * 900, rng() * COURSE_LEN);
      if (!Number.isFinite(h)) bad++;
      mn = Math.min(mn, h); mx = Math.max(mx, h);
    }
    ok('terrain finite', bad === 0, 'range ' + mn.toFixed(1) + '..' + mx.toFixed(1));
    ok('runway flat', Math.abs(terrainH(0, 300)) < 0.01 && Math.abs(terrainH(10, 600)) < 0.01);
    // Projection sanity.
    let pBad = 0;
    for (let i = 0; i < 200; i++) {
      const p = project((rng() * 2 - 1) * 600, 50 + rng() * 100, S.cam.z + 100 + rng() * 1000);
      if (p && (!Number.isFinite(p.x) || !Number.isFinite(p.y))) pBad++;
    }
    ok('projection finite', pBad === 0);
    // Scripted flight: autopilot toward each ring with fixed steps.
    resetGame(); S.mode = 'playing';
    const steps = 60 * 90; // 90 seconds of game time
    let ringsHit = 0, crashes = 0;
    for (let s = 0; s < steps; s++) {
      if (S.mode !== 'playing') break;
      const p = S.plane, r = rings[S.nextRing];
      // Simple autopilot: aim at the next ring, or the runway on return.
      const tx = S.phase === 'course' ? (r ? r.x : 0) : 0;
      const ty = S.phase === 'course' ? (r ? r.y : 60) : 8;
      const tz = S.phase === 'course' ? (r ? r.z : 12000) : 320;
      const wantYaw = Math.atan2(tx - p.x, tz - p.z);
      let dyaw = wantYaw - p.yaw;
      while (dyaw > Math.PI) dyaw -= Math.PI * 2;
      while (dyaw < -Math.PI) dyaw += Math.PI * 2;
      keys.ArrowLeft = dyaw < -0.05; keys.ArrowRight = dyaw > 0.05;
      const wantPitch = Math.atan2(ty - p.y, Math.hypot(tx - p.x, tz - p.z));
      keys.ArrowUp = wantPitch > 0.06; keys.ArrowDown = wantPitch < -0.06;
      keys.KeyW = p.speed < 95; keys.KeyS = p.speed > 120;
      const before = S.nextRing;
      update(1 / 60);
      if (S.nextRing > before) ringsHit = S.nextRing;
      if (S.mode === 'crashed') { crashes++; S.crashT = 99; S.lives = Math.max(1, S.lives); resetPlane(false); S.mode = 'playing'; }
      if (S.mode === 'win' || S.mode === 'gameover') break;
    }
    ok('autopilot rings', ringsHit >= 4, ringsHit + '/12 rings in 90s, crashes ' + crashes + ', score ' + S.score + ', final mode ' + S.mode);
    ok('no NaN in plane state', Number.isFinite(S.plane.x) && Number.isFinite(S.plane.y) && Number.isFinite(S.plane.z) && Number.isFinite(S.plane.speed));
    // Render one real frame to prove the draw path runs without errors.
    drawSky(); drawClouds(0.016); drawTerrain();
    rings.forEach((r, i) => drawRing(r, i));
    drawPlaneShadow(); drawPlane(); drawHUD();
    ok('render pass', true, 'sky+terrain+rings+plane+hud drew without throwing');
  } catch (e) {
    out.push('FAIL exception — ' + (e && e.message));
  }
  const div = document.getElementById('selftest');
  div.style.display = 'block';
  div.textContent = 'SELFTEST\n' + out.join('\n');
  document.title = 'SELFTEST ' + (out.every(l => l.indexOf('FAIL') !== 0) ? 'PASS' : 'FAIL');
}

// ---------- boot ----------
(function boot() {
  const shot = params.get('shot');
  if (params.get('selftest') === '1') {
    // Headless verification run: no animation loop, just the checks.
    S.cam.x = 0; S.cam.y = 80; S.cam.z = 0; S.cam.yaw = 0;
    runSelfTest();
    return;
  }
  if (shot) {
    setupShot(shot);
    // One frozen frame (plus the title attract frame when shot=title).
    if (shot === 'title') { frame(performance.now()); }
    else { S.t = 1; frame(performance.now()); }
    return;
  }
  resetGame();
  S.mode = 'title';
  requestAnimationFrame(frame);
})();
